-- Landing catalog courses (formerly static in features/landing/data.ts).
-- Base text is English; other languages live in i18n (see 20260928000000_content_i18n.sql).

alter table courses add column if not exists students integer not null default 0;
alter table courses add column if not exists duration_months integer;
alter table courses add column if not exists badge text check (badge is null or badge in ('bestseller', 'new', 'popular'));

on conflict (slug) do nothing;
